    def findPrimePairs(self, n: int) -> List[List[int]]:
        # Edge case: if n < 4, no prime pairs possible
        # since smallest prime is 2, and 2+2=4
        if n < 4:
            return []

        # Use Sieve of Eratosthenes to find all primes up to n
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime

        for i in range(2, int(n**0.5) + 1):
            if is_prime[i]:
                # Mark all multiples of i as not prime
                for j in range(i * i, n + 1, i):
                    is_prime[j] = False

        # Find all prime pairs (x, y) where x + y = n and x <= y
        result = []

        # Check all possible values of x from 2 to n//2
        # (x must be at least 2 since 1 is not prime)
        # (x must be at most n//2 since x <= y and x + y = n)
        for x in range(2, n // 2 + 1):
            y = n - x
            # Check if both x and y are prime
            if is_prime[x] and is_prime[y]:
                result.append([x, y])

        return result

